create table if not exists public.cp_group_media_views (message_id uuid not null references public.cp_group_messages(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,viewed_at timestamptz not null default now(),primary key(message_id,user_id));
alter table public.cp_group_media_views enable row level security;
revoke all on public.cp_group_media_views from anon,authenticated;
create policy "deny_group_media_views_api" on public.cp_group_media_views for all to authenticated using(false) with check(false);
create or replace function public.send_group_message_secure(p_group_id uuid,p_body text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); mid uuid; allowed boolean:=true; begin if uid is null then raise exception 'Unauthorized'; end if; select coalesce(gs.send_messages,true) into allowed from public.group_settings gs where gs.group_id=p_group_id; if not allowed and not exists(select 1 from public.group_members gm where gm.group_id=p_group_id and gm.user_id=uid and gm.role in ('owner','admin') and gm.left_at is null) then raise exception 'Only group admins can send messages right now'; end if; if not exists(select 1 from public.groups g join public.group_members gm on gm.group_id=g.id where g.id=p_group_id and gm.user_id=uid and gm.left_at is null and g.activated_at is not null and coalesce(g.expires_at,now()+interval '1 second')>now()) then raise exception 'Group is not active'; end if; if length(trim(p_body))=0 or length(p_body)>2000 then raise exception 'Invalid message'; end if; insert into public.cp_group_messages(group_id,user_id,body) values(p_group_id,uid,trim(p_body)) returning id into mid; perform public.apply_bc_delta(uid,-1,'Group message','group_message',mid); return jsonb_build_object('id',mid,'created_at',now(),'bc_charged',1); end $$;
create or replace function public.send_group_media_secure(p_group_id uuid,p_message_type text,p_media_path text,p_mime_type text default null,p_duration_seconds integer default null,p_body text default '') returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); mid uuid; begin if uid is null then raise exception 'Unauthorized'; end if; if p_message_type not in ('image','video','audio') then raise exception 'Invalid media type'; end if; if p_media_path is null or split_part(p_media_path,'/',1)<>p_group_id::text or split_part(p_media_path,'/',2)<>uid::text then raise exception 'Invalid media path'; end if; if not exists(select 1 from public.groups g join public.group_members gm on gm.group_id=g.id where g.id=p_group_id and gm.user_id=uid and gm.left_at is null and g.activated_at is not null and coalesce(g.expires_at,now()+interval '1 second')>now()) then raise exception 'Group is not active'; end if; if not coalesce((select gs.send_messages from public.group_settings gs where gs.group_id=p_group_id),true) and not exists(select 1 from public.group_members gm where gm.group_id=p_group_id and gm.user_id=uid and gm.role in ('owner','admin') and gm.left_at is null) then raise exception 'Only group admins can send messages right now'; end if; insert into public.cp_group_messages(group_id,user_id,body,message_type,media_path,mime_type,duration_seconds) values(p_group_id,uid,left(coalesce(trim(p_body),''),2000),p_message_type,p_media_path,p_mime_type,p_duration_seconds) returning id into mid; perform public.apply_bc_delta(uid,-1,'Group media message','group_media',mid); return jsonb_build_object('id',mid,'created_at',now(),'bc_charged',1); end $$;
create or replace function public.claim_group_media_view_once(p_message_id uuid) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); gid uuid; mt text; begin if uid is null then raise exception 'Unauthorized'; end if; select group_id,message_type into gid,mt from public.cp_group_messages where id=p_message_id; if gid is null or mt not in ('image','video') then raise exception 'Invalid view-once media'; end if; if not exists(select 1 from public.group_members where group_id=gid and user_id=uid and left_at is null) then raise exception 'Not a group member'; end if; insert into public.cp_group_media_views(message_id,user_id) values(p_message_id,uid,now()) on conflict do nothing; return found; end $$;
grant execute on function public.send_group_message_secure(uuid,text),public.send_group_media_secure(uuid,text,text,text,integer,text),public.claim_group_media_view_once(uuid) to authenticated;
revoke execute on function public.send_group_message_secure(uuid,text),public.send_group_media_secure(uuid,text,text,text,integer,text),public.claim_group_media_view_once(uuid) from anon;